query PortalRequest {
  listTasks {
    results {
      id
      description
      accessExpiresAt
      requesterName
      organizationName
      organizationTimezone
      requestedPeriod {
        end
      }
      focusQuestionnaire {
        id
        title
        description
        item
      }
    }
  }
}

sha256:6341ec230840419c6f72011e235ac2c55:
mutation PortalSubmitResponse($input: SubmitQuestionnaireResponseFromPortalInput!) {
  submitQuestionnaireResponseFromPortal(input: $input) {
    result {
      id
    }
    errors {
      message
    }
  }
}
